-- 1. Sources
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3119, 'https://www.uio.no/english/research/phd/before-applying/', 'Before applying - PhD (admission criteria and funding) | University of Oslo (official)', 'uio.no', 'scholarship', now(), true, true, now()), (3120, 'https://www.uib.no/en/phd', 'Pursuing your PhD at UiB | University of Bergen (official)', 'uib.no', 'scholarship', now(), true, true, now());

-- 2. Record 346 (UiO) rewrite
UPDATE scholarships SET title = $$University of Oslo Doctoral Research Fellowships$$, provider = $$University of Oslo$$, country = $$Norway$$, coverage_type = $$Full Funding$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$NOK$$, award_period = $$year$$, award_basis = $$variable$$, deadline = $$No single deadline - funded PhD positions (doctoral research fellowships) are advertised on an ongoing basis on the UiO vacant-positions pages, each advert with its own closing date$$, deadline_date = NULL, deadline_type = $$rolling$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$continuous$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["All"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$At the University of Oslo a doctorate is not a scholarship but a funded position: the university states that admission to a PhD programme requires a relevant five-year Master's degree with a good grade (or equivalent qualifications approved by the faculty), available supervision capacity in the subject area, and sufficient funding for the entire three years of full-time study - and that the most common type of funding is employment as a doctoral research fellow. A doctoral research fellowship is temporary employment at a UiO unit, normally granted for three years without compulsory work or four years with compulsory work (usually teaching); fellowships are tied to a subject, subject area, project or unit and are announced by the relevant faculty, department, museum or centre, with new positions advertised on an ongoing basis. There is no tuition fee, and PhD candidates do not have student status in Norway - so there is no entitlement to support from the Norwegian State Educational Loan Fund or to regular student accommodation. Admission with external funding is also possible if full funding covering living expenses and necessary working capital is documented and the progress plan is at least 50 per cent. UiO's eight faculties each run their own PhD programme (a 30-credit educational component plus independent research work of about 2.5 years). Because the appointment is an employment contract, the value is the salary stated in each individual advert - no single figure exists and none is stored. This record previously presented the UiO PhD route as a generic "Unspecified" scholarship anchored to a vacancies URL that now returns 404; it is rewritten to match the NTNU record (425) treatment.$$ , requirements = $$Find an advertised doctoral research fellow position on the UiO vacant-positions pages and apply to that specific position - funding must be in place before admission and there is no separate scholarship round. Hold a relevant five-year Master's degree with a good grade or equivalent qualifications approved by the faculty (faculties may impose additional qualification requirements), and note that the faculty must have supervision capacity in the subject area. Fellowships normally run three years without compulsory work or four years with compulsory work (usually teaching), as written into the employment contract. If you already hold external funding, you may apply for admission with that funding instead: document full funding for the whole period (living expenses plus necessary working capital), the affiliation to an academic community that the faculty requires, and a progress plan of at least 50 per cent (some faculties have stricter progress requirements). Applications are submitted to the faculty whose PhD programme you want to join - familiarize yourself with that programme's own rules and guidelines before applying.$$ , website_url = $$https://www.uio.no/english/research/phd/before-applying/$$, source_url = $$https://www.uio.no/english/research/phd/before-applying/$$, application_url = $$https://www.uio.no/english/about/vacancies/academic/$$, funding_type = $$Salaried PhD position at a Norwegian university, filled through the vacancy process rather than through a scholarship competition$$, tuition_coverage = $$The appointment is an employment contract that pays a salary for three years, or four where the position includes compulsory work (usually teaching), and there is no tuition fee. The salary is set per position and stated in each advert, so no figure is published at programme level and none is stored. Housing is not part of the appointment: PhD candidates have no student status and are not entitled to regular student accommodation or Loan Fund support, so Oslo living costs must be covered from the salary.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = $$Not provided - PhD candidates are temporary employees without student status and are not entitled to regular student accommodation (UiO).$$ , application_fee = NULL, english_requirements = $$No single university-wide score applies; language requirements follow the advertised position and the admitting faculty's PhD programme rules - check the advert and the programme pages.$$ , required_documents = $$["Application to an advertised doctoral research fellow position at UiO", "Master's degree certificate and transcripts (relevant five-year degree with a good grade, or faculty-approved equivalent)", "Project description / research plan where the advert or programme requires one", "Curriculum vitae", "Letters of recommendation where the position requires them", "For the external-funding route: documentation of full funding for the entire study period"]$$, application_status = $$open$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 158, notes = $$PASS 118 REWRITE 2026-10-28 (Norway cluster): rewritten from rel 4 to rel 10 on first-hand fetched evidence and aligned with record 425 (NTNU Doctoral Research Fellowships). The stored importer URL (uio.no/english/about/vacancies/phd/) now returns 404. UiO's fetched PhD pages (uio.no/english/research/phd/ and /before-applying/, new source 3119) state the funding-as-employment model: documented funding for all 3 years, fellowships = temporary employment (3 years, or 4 with compulsory work usually teaching), advertised on an ongoing basis, no tuition fee, no student status. Title pluralized (Fellowship -> Fellowships) to match records 424/425. No salary figure stored - each advert states its own range; min_gpa/min_ielts NULL (no single published figure). Root-domain source link 2650 replaced by 3119; us 511 synced (its importer 'Grade B or better ECTS' note removed - not in the fetched UiO text, which says 'good grade').$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 346;

-- 3. Record 424 (UiB) rewrite
UPDATE scholarships SET title = $$University of Bergen PhD Research Fellowships$$, provider = $$University of Bergen$$, country = $$Norway$$, coverage_type = $$Full Funding$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$NOK$$, award_period = $$year$$, award_basis = $$variable$$, deadline = $$No single deadline - funded PhD positions (research fellowships) are announced on the UiB vacant-positions pages, each advert with its own closing date$$, deadline_date = NULL, deadline_type = $$rolling$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$continuous$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["All"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$At the University of Bergen a doctorate is not a scholarship but a funded position: UiB states that as a PhD research fellow you receive a salary and enjoy the rights of a temporary employee - including paid leave if you become a parent or become ill, with the PhD end-date extended in that case. Admission normally requires a completed Master's education of at least five years, a PhD project description, and full funding; the remaining requirements differ between faculties, academic fields and the specific vacancy. Funding usually comes in one of two ways: apply for a PhD research fellowship announced on UiB's vacant-positions pages (some faculties admit you to the PhD programme in the same process, at others recruitment and admission are separated), or hold a research-fellowship position paid by an institution or company outside UiB and apply for admission to the PhD programme separately through the relevant faculty. The work combines in-depth research with training, teaching and dissemination, with possibilities for research stays and conferences abroad. Because the appointment is an employment contract, the value is the salary of the individual position - no single figure exists and none is stored. This record previously presented the UiB PhD route as a generic "Unspecified" scholarship; it is rewritten to match the NTNU record (425) treatment.$$ , requirements = $$Find an advertised PhD research fellowship on UiB's vacant-positions pages and apply to that position - or secure funding/an employer outside UiB and apply for admission to the PhD programme separately through the relevant faculty. Full funding is an admission requirement and there is no separate scholarship round. Hold a Master's degree (completed Master's education, normally of at least five years) and prepare a PhD project description; expect faculty-, field- and vacancy-specific requirements on top - UiB's seven faculties (Humanities; Science and Technology; Medicine; Social Sciences; Law; Psychology; Fine Art, Music and Design) publish their own doctoral-education pages, and your host faculty can tell you whether recruitment and admission run in one process or separately. As a PhD research fellow you are a temporary employee with a salary and employee rights; parental or sick leave extends the end-date.$$ , website_url = $$https://www.uib.no/en/phd$$, source_url = $$https://www.uib.no/en/phd$$, application_url = $$https://www.uib.no/en/about/84777/vacant-positions-uib$$, funding_type = $$Salaried PhD position at a Norwegian university, filled through the vacancy process rather than through a scholarship competition$$, tuition_coverage = $$The appointment is an employment contract that pays a salary with temporary-employee rights, and Norwegian doctoral candidates are not charged tuition - the admission hurdle at UiB is full funding, not a tuition charge. The salary is set per position and stated in each advert, so no figure is published at programme level and none is stored. Whether the salary covers living costs depends on the individual contract and on Bergen housing costs, which are not part of the appointment.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$No single university-wide score applies; language requirements follow the advertised position and the admitting faculty's doctoral-education rules - check the advert and the faculty pages.$$ , required_documents = $$["Application to an advertised PhD research fellowship position at UiB", "Master's degree certificate and transcripts (normally a five-year Master's education)", "PhD project description", "Curriculum vitae", "Letters of recommendation where the position requires them", "For the external-funding route: documentation of the external fellowship/employment funding for separate admission via the faculty"]$$, application_status = $$open$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 272, notes = $$PASS 118 REWRITE 2026-10-28 (Norway cluster): rewritten from rel 4 to rel 10 on first-hand fetched evidence and aligned with record 425 (NTNU Doctoral Research Fellowships). UiB's fetched 'Pursuing your PhD at UiB' page (uib.no/en/phd, last updated 25.09.2026; new source 3120) states the funding-as-employment model: salary + temporary-employee rights (paid parental/sick leave extends the end-date), Master's normally at least five years, full funding required, fellowships announced as vacant positions, external-funding route via the faculty. No salary figure stored; min_gpa/min_ielts NULL. university_id set to 272 (University of Bergen exists in the catalogue) and us 709 created; root-domain source link 2648 replaced by 3120. 'Not charged tuition' follows the fetched UiO Norway statement ('there is no tuition fee') and the record-425 precedent.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 424;

-- 4. university_scholarships sync (511 for 346 @ UiO 158; new 709 for 424 @ UiB 272)
UPDATE university_scholarships SET scholarship_name = $$University of Oslo Doctoral Research Fellowships$$, availability_status = $$available$$, funding_type = $$Salaried doctoral research fellow positions (employment, not a scholarship award)$$, max_scholarship = $$Salary per advertised position (3 years, or 4 with compulsory work); no tuition fee$$, covers_tuition = true, covers_living_expenses = true, valued_aspect = $$PhD as paid employment: salary with employee rights, no tuition fee, positions advertised on an ongoing basis$$, eligibility_notes = $$Relevant five-year Master's degree with a good grade (or faculty-approved equivalent); documented funding for the full 3-year period is an admission precondition - apply to advertised doctoral research fellow vacancies (each with its own deadline) or document external funding. PhD candidates have no student status (no Loan Fund support or student-housing entitlement).$$ , official_url = $$https://www.uio.no/english/research/phd/before-applying/$$, source_url = $$https://www.uio.no/english/research/phd/before-applying/$$, verification_status = $$verified_official_source$$, last_verified_at = now() WHERE id = 511;

INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at, created_at) VALUES (709, 272, 424, $$University of Bergen PhD Research Fellowships$$, 'available', $$Salaried doctoral research fellow positions (employment, not a scholarship award)$$, $$Salary per advertised position; no tuition fee$$, true, true, $$PhD as paid employment: salary with temporary-employee rights (paid parental/sick leave extends the end-date)$$, $$Master's degree (normally at least five years of education) plus a PhD project description; full funding is required for admission - apply to advertised PhD research fellowship vacancies at UiB, or bring external funding/an employer and apply for admission separately via the faculty.$$ , 'https://www.uib.no/en/phd', 'https://www.uib.no/en/phd', 'verified_official_source', now(), now());

